@app.get("/v1/harbor/encoders")
async def harbor_encoders_status(_: bool = Depends(verify_api_key)):
    return _harbor_encoders.pool_status(_server_state.engine_pool)


@app.post("/v1/harbor/encoders/{modality}/{action}")
async def harbor_encoders_action(modality: str, action: str, request: FastAPIRequest,
                               _: bool = Depends(verify_api_key)):
    try:
        body = await request.json()
    except ValueError:
        body = None
    model = body.get("model") if isinstance(body, dict) else None
    if not isinstance(model, str) or not model:
        return JSONResponse(status_code=422, content={"error": "model_required"})
    status, content = await _harbor_encoders.act(
        _server_state.engine_pool, resolve_model_id(model), modality, action)
    return JSONResponse(status_code=status, content=content)


